def decode(encoded: str, original: str, message: str) -> str:
    """
    Builds a mapping from each character in `encoded` to the corresponding
    character in `original` and decodes `message` using that mapping.
    If the mapping contains a contradiction or does not cover all 26
    uppercase letters, the function returns "Failed".
    """
    # Basic sanity check: encoded and original must be the same length
    if len(encoded) != len(original):
        return "Failed"

    # Build mapping, check for contradictions
    mapping = {}
    for e_char, o_char in zip(encoded, original):
        if e_char in mapping:
            if mapping[e_char] != o_char:
                return "Failed"  # contradiction
        else:
            mapping[e_char] = o_char

    # Ensure all 26 uppercase letters are present in mapping
    if len(mapping) < 26:
        return "Failed"

    # Decode the message
    decoded_chars = []
    for ch in message:
        if ch not in mapping:
            return "Failed"  # unmapped character
        decoded_chars.append(mapping[ch])

    return ''.join(decoded_chars)

