def count_coprime_pairs(x0: int, y0: int) -> int:
    """Count ordered pairs (P, Q) such that gcd(P, Q) = x0 and lcm(P, Q) = y0.

    Args:
        x0: Desired greatest common divisor of the pair.
        y0: Desired least common multiple of the pair.

    Returns:
        The number of ordered positive integer pairs (P, Q) satisfying the conditions.
    """
    if x0 <= 0 or y0 <= 0:
        return 0
    if y0 % x0 != 0:
        return 0
    n = y0 // x0
    count = 0
    limit = int(math.isqrt(n))
    for a in range(1, limit + 1):
        if n % a == 0:
            b = n // a
            if math.gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
    return count

