def generate_numbers(n, rules) -> int:
    """Generate all unique numbers reachable from the original integer n by repeatedly
    applying digit transformation rules.

    Parameters
    ----------
    n : int
        The original number.
    rules : list of tuple[int, int]
        Each tuple (x, y) indicates that digit x can be transformed into y.

    Returns
    -------
    int
        The count of unique numbers that can be generated, including n itself.
    """
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    # Build mapping from digit to list of possible replacements
    mapping = {}
    for rule in rules:
        if not isinstance(rule, tuple) or len(rule) != 2:
            raise ValueError("Each rule must be a tuple of two integers")
        x, y = rule
        if not (isinstance(x, int) and isinstance(y, int)):
            raise ValueError("Rule elements must be integers")
        mapping.setdefault(x, []).append(y)

    visited = {n}
    queue = [n]
    while queue:
        current = queue.pop(0)
        s = str(current)
        for i, ch in enumerate(s):
            d = int(ch)
            if d in mapping:
                for y in mapping[d]:
                    new_s = s[:i] + str(y) + s[i+1:]
                    new_num = int(new_s)
                    if new_num not in visited:
                        visited.add(new_num)
                        queue.append(new_num)
    return len(visited)

